import gzip, heapq, math, pyBigWig, concurrent.futures, sys, time
# load top 60 intervals from unknown
heap=[]
with gzip.open('inputs/reverse.encode.q1.tsv.gz','rt') as f:
    for line in f:
        if not line.strip(): continue
        c,s,e,v=line.rstrip().split('\\t')[:4]; rec=(float(v),c,int(s),int(e))
        if len(heap)<60: heapq.heappush(heap,rec)
        elif rec[0]>heap[0][0]: heapq.heapreplace(heap,rec)
intervals=sorted(heap, reverse=True)
target=[x[0] for x in intervals]
def corr(x,y):
    n=len(x); mx=sum(x)/n; my=sum(y)/n
    sx=sum((a-mx)**2 for a in x); sy=sum((b-my)**2 for b in y)
    return float('nan') if sx==0 or sy==0 else sum((a-mx)*(b-my) for a,b in zip(x,y))/math.sqrt(sx*sy)
def score(row):
    fields=row.rstrip('\\n').split('\\t')
    exp,bwacc,url,reps,size=fields[:5]; bios=fields[5] if len(fields)>5 else ''
    try:
        bw=pyBigWig.open(url); chroms=bw.chroms(); vals=[]
        for _,c,s,e in intervals:
            if c not in chroms: vals.append(0.0); continue
            v=bw.stats(c,s,min(e,chroms[c]),type='mean')[0]
            vals.append(0.0 if v is None or math.isnan(v) else v)
        bw.close(); return (corr(target,vals), exp,bwacc,bios,'ok')
    except Exception as exc:
        return (float('nan'), exp,bwacc,bios,type(exc).__name__+':'+str(exc)[:40])
rows=open('work/dnase_encode4_signal_manifest_s3.tsv').read().splitlines()[1:]
print('rows',len(rows),'intervals',len(intervals), flush=True)
out=[]; start=time.time(); done=0
with concurrent.futures.ThreadPoolExecutor(max_workers=24) as ex:
    futs=[ex.submit(score,r) for r in rows]
    for fut in concurrent.futures.as_completed(futs):
        out.append(fut.result()); done+=1
        if done%100==0: print('done',done,'elapsed',round(time.time()-start,1), flush=True)
out.sort(key=lambda x: (-999 if math.isnan(x[0]) else x[0]), reverse=True)
with open('work/local_top60_ranking.tsv','w') as o:
    o.write('rank\\tpearson\\texperiment\\tbigwig\\tbiosample\\tstatus\\n')
    for i,r in enumerate(out[:100],1): o.write(f'{i}\\t{r[0]:.6f}\\t{r[1]}\\t{r[2]}\\t{r[3]}\\t{r[4]}\\n')
print(open('work/local_top60_ranking.tsv').read()[:5000])
PY"

