/bin/bash -lc "python3 - <<'PY'
import requests
base='https://www.encodeproject.org'; h={'accept':'application/json'}
for exp in ['ENCSR251INE','ENCSR206KJN','ENCSR111LTT','ENCSR342OGI','ENCSR541PUY']:
 e=requests.get(f'{base}/experiments/{exp}/?format=json',headers=h,timeout=30).json()
 print('\\n',exp,e.get('biosample_ontology',{}).get('term_name'),e.get('biosample_summary'))
 for f in e['files']:
  if f.get('file_format')=='bam' and f.get('output_type')=='alignments' and f.get('assembly')=='GRCh38' and f.get('status')=='released' and 'encode:dnase-alignment-filtering-step-version-v-1' in (f.get('analysis_step_version',{}).get('aliases') or []):
   total='?'
   for qm in f.get('quality_metrics') or []:
    if isinstance(qm,dict) and 'SamtoolsStatsQualityMetric' in qm.get('@type',[]): total=qm.get('raw total sequences')
   print(f['accession'],total,f.get('cloud_metadata',{}).get('url'))
PY"

